document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeOverlay();$('.shell')?.classList.remove('nav-open');return;}if($('#overlay').innerHTML&&e.key==='Tab'){const focusable=Array.from($('#overlay').querySelectorAll('button:not(:disabled),a[href],input,select,textarea')).filter(x=>x.getClientRects().length);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}return;}if((e.metaKey||e.ctrlKey)&&e.key==='Enter'&&e.target.id==='prompt'){e.preventDefault();$('[data-action="send"]').click();return;}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='n'){e.preventDefault();state.selectedSkill=null;state.prompt='';state.attachments=[];navigate('home');$('#prompt').focus();return;}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('[data-action="global-search"]').click();return;}if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||e.target.isContentEditable||$('#overlay').innerHTML)return;if(state.route==='contract'){if(e.key==='j'||e.key==='k'){e.preventDefault();state.selected=(state.selected+(e.key==='j'?1:3))%4;render();}if(e.key==='a'||e.key==='r')$(`[data-action="${e.key==='a'?'accept':'reject'}"][data-id="${state.selected}"]`)?.click();}});
